BEGIN
 FOR gid IN SELECT guild_id FROM pb_discord_settings UNION SELECT guild_id FROM wosb_territory_settings UNION SELECT guild_id FROM wosb_diplomacy LOOP
 PERFORM pg_advisory_xact_lock(hashtext(gid||':snapshot-448'));
 IF EXISTS(SELECT 1 FROM wosb_snapshot_seeds WHERE guild_id=gid AND seed_key='battle-map-448') THEN CONTINUE; END IF;
 INSERT INTO wosb_diplomacy(guild_id,revision,data,updated_by) VALUES(gid,1,snapshot->'diplomacy','snapshot-448') ON CONFLICT(guild_id) DO UPDATE SET data=excluded.data,revision=wosb_diplomacy.revision+1,updated_by=excluded.updated_by,updated_at=now();
 FOR p IN SELECT value FROM jsonb_array_elements(snapshot->'ports') LOOP
 INSERT INTO wosb_territories(guild_id,port_key,name,owner_tag,taxing_tag,window_start,window_end,time_zone,game_offset_minutes,protected_until,protection_started_at,taxes,tension_battle_at,updated_by)
 VALUES(gid,p->>'port_key',p->>'name',p->>'owner_tag',p->'taxes'->0->>'tag',p->>'window_start',p->>'window_end','Etc/GMT-4',0,(p->>'protected_until')::timestamptz,CASE WHEN p->>'protected_until' IS NOT NULL THEN '2026-10-24T17:10:06Z'::timestamptz END,p->'taxes',(p->>'tension_battle_at')::timestamptz,'snapshot-448')
 ON CONFLICT(guild_id,port_key) DO UPDATE SET name=excluded.name,owner_tag=excluded.owner_tag,taxing_tag=excluded.taxing_tag,window_start=excluded.window_start,window_end=excluded.window_end,time_zone=excluded.time_zone,game_offset_minutes=0,protected_until=excluded.protected_until,protection_started_at=excluded.protection_started_at,taxes=excluded.taxes,tension_battle_at=excluded.tension_battle_at,version=wosb_territories.version+1,updated_by=excluded.updated_by,updated_at=now();
 END LOOP;
 INSERT INTO wosb_snapshot_seeds(guild_id,seed_key) VALUES(gid,'battle-map-448');
 END LOOP;
END $seed$;
